        ib.missing_count,
        ib.failed_count
    FROM "sales-pipe".import_batches ib
    LEFT JOIN "sales-pipe".profiles p ON p.id = ib.uploaded_by
    ORDER BY ib.created_at DESC
    LIMIT 100;
END;
